def rotate_90(grid):
    """Rotate 90 degrees clockwise"""
    n = len(grid)
    return [list(row) for row in zip(*grid[::-1])]

def rotate_ccw(grid):
    """Rotate 90 degrees counter-clockwise"""
    n = len(grid)
    return [list(row) for row in zip(*grid)][::-1]

def rotate_180(grid):
    """Rotate 180 degrees"""
    n = len(grid)
    return [row[::-1] for row in grid[::-1]]

def transform(grid):
    n = len(grid)
    m = len(grid[0])

    result = [[0] * (2 * m) for _ in range(2 * n)]

    # Top-left: original
    for r in range(n):
        for c in range(m):
            result[r][c] = grid[r][c]

    # Top-right: 90° clockwise rotation
    for r in range(n):
        for c in range(m):
            result[r][m + c] = rotate_90(grid)[r][c]

    # Bottom-left: 90° counter-clockwise rotation
    for r in range(n):
        for c in range(m):
            result[n + r][c] = rotate_ccw(grid)[r][c]

    # Bottom-right: 180° rotation
    for r in range(n):
        for c in range(m):
            result[n + r][m + c] = rotate_180(grid)[r][c]

    return result

